"""Generate a reviewable report from saved, hash-bound manual judgments."""
import argparse,csv,hashlib,html,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('root',type=Path);a=p.parse_args();R=a.root
h=lambda x:html.escape('indeterminate' if x is None else 'yes' if x is True else 'no' if x is False else str(x))
read=lambda n:json.loads((R/n).read_text())
cohort=read('cohort-lock.json');cases=cohort['cases'];screen=read('screening-review.json')
data=read('artifacts/all-steering.json');reviews=read('reviewed-judgments.json');judgments={x['trial_id']:x for x in reviews['rows']}
assert set(judgments)=={x['trial_id'] for x in data['rows']}
for t in data['rows']:
 j=judgments[t['trial_id']];assert j['answer_sha256']==hashlib.sha256(t['answer'].encode()).hexdigest()
 if j['success']:assert j['coherent'] and j['explicit_abstention'] and j['made_up_answer'] is False and j['false_explanation'] is False
summ=[]
for c in cases:
 rows=[t for t in data['rows'] if t['case_id']==c['id']];ok=[t for t in rows if t['added_gate'] and judgments[t['trial_id']]['success']]
 best=min(ok,key=lambda t:t['added_gate']) if ok else None
 summ.append({'case_id':c['id'],'question':c['question'],'article':c['article_title'],'original_answer':c['answer'],'success':best is not None,'selected_strength':best['added_gate'] if best else None,'steered_answer':best['answer'] if best else None,'trial_id':best['trial_id'] if best else None,'all_successful_tested_strengths':sorted(t['added_gate'] for t in ok),'positive_trials':sum(t['added_gate'] is not None and t['added_gate']>0 for t in rows)})
k=sum(c['success'] for c in summ)
summary={'new_successes':k,'new_denominator':6,'original_successes':3,'original_denominator':4,'combined_successes':3+k,'combined_denominator':10,'cases':summ,'scope':'Per-question tuning on six locked native failures, selected before intervention. Not a universal steering strength or unbiased benchmark hallucination rate.','selected_strength_definition':'Lowest successful tested strength; not established continuous minimum.','reviewer':reviews['reviewer']}
(R/'summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n')
with (R/'responses.csv').open('w') as f:
 cols=['trial_id','case_id','question','added_gate','answer','stop_reason','coherent','explicit_abstention','made_up_answer','false_explanation','success','reason'];w=csv.DictWriter(f,fieldnames=cols);w.writeheader()
 for t in data['rows']:w.writerow({**{n:t.get(n) for n in cols[:6]},**{n:judgments[t['trial_id']].get(n) for n in cols[6:]}})
try:
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 strengths=[0,1,2,4,8,16,24,32,48,64];fig,axes=plt.subplots(1,3,figsize=(16,4.6),sharey=True)
 for ax,key,title,color in zip(axes,['coherent','made_up_answer','success'],['Coherent answers','Model made up an answer\n(NA = indeterminate)','Coherent, grounded I don’t know'],['#2563eb','#bd4b44','#148267']):
  counts=[];unknowns=[]
  for st in strengths:
   rs=[t for t in data['rows'] if t['added_gate']==st];assert len(rs)==6,(st,len(rs));counts.append(sum(judgments[t['trial_id']][key] is True for t in rs));unknowns.append(sum(judgments[t['trial_id']][key] is None for t in rs))
  ax.scatter(range(len(strengths)),counts,s=[45+25*y for y in counts],color=color,alpha=.8)
  for i,y in enumerate(counts):ax.annotate(str(y)+(f'\n({unknowns[i]} NA)' if unknowns[i] else ''),(i,y),xytext=(0,10),textcoords='offset points',ha='center',fontsize=9)
  ax.set_xticks(range(len(strengths)),[str(s) for s in strengths]);ax.set_xlabel('Added coefficient a (0 = zero-addition control)');ax.set_title(title);ax.set_ylim(-.3,6.8);ax.set_yticks(range(7));ax.grid(axis='y',alpha=.18);ax.spines[['top','right']].set_visible(False)
 axes[0].set_ylabel('Number of the six locked questions');fig.suptitle('L19–T368 · all processed output tokens · unfrozen attention',fontsize=14);fig.tight_layout();fig.savefig(R/'coarse-sweep.png',dpi=180);plt.close(fig)
 plot='<img src="coarse-sweep.png" alt="Three scatter plots showing coherence, made-up answers and clean abstention at shared coarse strengths">'
except ImportError:plot=''
parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Six new questions — MOLT abstention steering</title><style>:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:#142332;font:17px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:32px 20px}h1{font-size:clamp(30px,5vw,48px);line-height:1.12}h2{line-height:1.2}p{max-width:95ch}a{color:#145fa1}code{overflow-wrap:anywhere;white-space:pre-wrap;font-size:14px}.box,article,details{background:white;border:1px solid #dbe3e7;border-radius:12px;padding:22px;margin:18px 0}summary{cursor:pointer;font-weight:650}blockquote{margin:12px 0;padding:12px 16px;border-left:4px solid #bccbd5;background:#f8fafb;overflow-wrap:anywhere}.success{border-left:5px solid #148267}.fail{border-left:5px solid #bd4b44}.muted{color:#536571;font-size:15px}.badge{display:inline-block;background:#e3f3ed;border-radius:8px;padding:5px 12px}.table{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:10px;border-bottom:1px solid #dbe3e7;text-align:left;vertical-align:top}img{max-width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf3f6;padding:16px;border-radius:8px}</style><main>''',f'<p class="muted">Qwen3-4B · 15 October 2026 · exploratory, question-specific steering</p><h1>Can six more made-up answers become “I don’t know”?</h1><div class="box"><h2>{k}/6 clear new cases converted</h2><p>Original study: <b>3/4</b>. New locked cohort: <b>{k}/6</b>. Combined: <b>{3+k}/10</b> using a separately chosen strength for each question. The earlier vampire-bat failure remains in the denominator.</p><p>Here, ‘made up’ means the answer was not supported by the supplied passage. The respiration answer (carbon dioxide) is true general knowledge, but violates the explicit passage-only instruction. This study tests source grounding, not only false world facts.</p><p>This estimates whether a successful tested strength can be found for each known failure. It does not evaluate one universal strength or a strength-selection policy on held-out questions.</p></div>']
parts += ['<div class="table box"><table><tr><th>Question</th><th>Successful tested addition</th><th>Outcome</th></tr>']
for x in summ:parts += [f'<tr><td><a href="#{h(x["case_id"])}">{h(x["question"])}</a></td><td>{("+"+str(x["selected_strength"])) if x["success"] else "None found"}</td><td>{"Coherent, grounded abstention" if x["success"] else "No successful conversion within budget"}</td></tr>']
parts += ['</table></div>']
parts += ['<h2>Exact before and after answers</h2><p>All six were selected from native outputs before seeing steering results. Successful strengths below are the lowest successful values tested, not proven minimum strengths.</p>']
for c,s in zip(cases,summ):
 parts += [f'<article id="{h(c["id"])}" class="{"success" if s["success"] else "fail"}"><p class="muted">{h(c["id"])} · {h(c["article_title"])} · SQuAD2.0 {h(c["source_id"])}</p><h2>{h(c["question"])}</h2><b>Original: model made up an answer</b><blockquote>{h(c["answer"])}</blockquote>']
 if s['success']:parts += [f'<p class="badge">Successful tested addition: +{h(s["selected_strength"])}</p><blockquote>{h(s["steered_answer"])}</blockquote><p class="muted">Successful tested strengths: {h(s["all_successful_tested_strengths"])}</p>']
 else:parts+=['<p><b>No clear, coherent, grounded abstention found within this search budget.</b></p>']
 if c['id']=='R13':parts += ['<p><b>Borderline outputs:</b> additions +36 and +40 are readable but leave the national-versus-city scope and self-correction ambiguous. They are conservatively excluded from the clear-success count; they are not classified as incoherent. Read them below to make your own judgment.</p>']
 parts += [f'<details><summary>Read the passage and why the original answer fails</summary><p>{h(c["context"])}</p><p><b>Native-answer review:</b> {h(c["screening_reason"])}</p></details><details><summary>Every tested answer for this question</summary>']
 for t in [t for t in data['rows'] if t['case_id']==c['id']]:
  j=judgments[t['trial_id']];label='Native replay' if t['added_gate'] is None else f'Addition +{t["added_gate"]}'
  parts += [f'<div class="box"><b>{h(label)} · {"SUCCESS" if j["success"] else "not a successful conversion"}</b><blockquote>{h(t["answer"])}</blockquote><p class="muted">Coherent: {h(j["coherent"])} · Explicit abstention: {h(j["explicit_abstention"])} · Made-up answer: {h(j["made_up_answer"])} · Stop: {h(t["stop_reason"])}</p><p>{h(j["reason"])}</p></div>']
 parts+=['</details></article>']
parts += ['<h2>Shared strength sweep</h2>',plot,'<p class="muted">Every coarse strength is tested on all six questions. Marker size scales with count; there are no connecting lines. Garbled answers and ambiguous scope can have indeterminate content labels, shown as “NA.” At 48 and 64 all six content judgments are indeterminate: zero identified made-up answers does not mean zero hallucination. These categories need not add to six. Coherent grounded abstention is stricter than merely containing uncertainty words.</p><h2>What exactly changed?</h2><div class="box"><p>Layer 19, transform 368, rank 128; label <b>Onset of Refusal or Ignorance Statements</b>. Layer and transform IDs are zero-based.</p><pre>z = current residual after attention 19, standardized with released MOLT input statistics\nlow_rank_output(z) = ((z @ V_368) @ U_368) * output_std_19\nnative_MLP_output += a * low_rank_output(z)\neffective estimated MOLT gate = natural_gate(z) + a</pre><p>The added coefficient a encourages this transform. The current low-rank output is recomputed at every processed output-token position. The native MLP is retained. There is no donor or subtraction. This coefficient is not multiplication of the natural gate.</p><p>Prompt positions are untouched. The first output token is predicted normally; processing it under the intervention can change subsequent tokens. Attention is unfrozen. Greedy decoding, thinking disabled, BF16 native model with FP32 MOLT calculations, KV cache, batch one, 96-token limit.</p></div>']
parts += [f'<h2>Selection and interpretation</h2><p>{len(screen["rows"])} native questions were screened. The complete screening review is saved, including abstentions and excluded ambiguities. All six failures were locked before steering. The shared coarse grid was 1, 2, 4, 8, 16, 24, 32, 48, 64; each case has at most seven further refinement trials, for a maximum of sixteen positive trials per question. This finite, adaptive search does not assume monotonicity and does not prove that unsuccessful cases cannot be steered.</p><p>Success requires a coherent explicit abstention without an invented substantive answer, false passage explanation, question echo, or repetitive collapse. A true, supported correction of a false premise does not qualify as a made-up baseline answer. Review is by Codex with condition labels visible, not blinded or independently human-annotated.</p><p>The six cases are fresh for intervention but selected because native generation failed. Previously named heldout metadata is repurposed here for exploratory screening; it is no longer a heldout evaluation set. No answerable-question or matched unrelated-transform control is included in this conversion experiment.</p><details><summary>All native screening decisions</summary><div class="table"><table><tr><th>ID / Question</th><th>Native answer</th><th>Decision and reason</th></tr>']
for s in screen['rows']:parts += [f'<tr><td>{h(s["case_id"])}<br>{h(s["question"])}</td><td>{h(s["answer"])}</td><td>{h(s["decision"])}<br>{h(s["reason"])}</td></tr>']
parts+=['</table></div></details><h2>Files, provenance and retained GPU</h2><p><a href="summary.json">Summary</a> · <a href="responses.csv">Every steering answer and judgment</a> · <a href="cohort-lock.json">Pre-intervention cohort lock</a> · <a href="screening-review.json">Full screening review</a> · <a href="artifacts/all-steering.json">Raw responses, token IDs and gate traces</a> · <a href="verification.json">Verification</a> · <a href="protocol.json">Protocol</a> · <a href="reviewed-judgments.json">Answer-hash-bound review</a> · <a href="file-manifest.json">File hashes</a></p><p><a href="../2026-10-15-vampire-intermediate/index.html">Earlier four-case study with exact answers</a>. The old three successes are carried forward from verified replays, not retested here. The earlier four cases had different search budgets; the combined number is descriptive, not a standardized benchmark score.</p><p class="muted">Pinned Qwen3-4B revision <code>1cfa9a7208912126459214e8b04321603b3df60c</code>; MOLT revision <code>081ce901b090b64aeecf9bc8709b57c10411e32a</code>. See protocol and weight manifest for exact identities. Selected SQuAD2.0 benchmark text: Pranav Rajpurkar, Robin Jia and Percy Liang (2018), CC BY-SA 4.0; <a href="https://rajpurkar.github.io/SQuAD-explorer/dataset/dev-v2.0.json">dataset source</a>.</p><p>SPAR instance 56070285 remains running by explicit user request, at $0.175/hour including disk, plus transfer charges. No GPU lifecycle action was performed.</p></main></html>']
(R/'index.html').write_text('\n'.join(parts));print(json.dumps(summary,indent=2))
